#!/usr/bin/env bash\nset -euo pipefail\n\n# Helper to create a mock df that reports low usage (50%)\nmock_df_low() {\n  cat <<'EOF' > /tmp/mockdf\n#!/usr/bin/env bash\necho \"Filesystem     1024-blocks    Used Available Capacity Mounted on\"\necho \"/dev/sda1       1000000   500000   500000  50% /\"\nEOF\n  chmod +x /tmp/mockdf\n}\n\n# Helper to create a mock df that reports high usage (90%)\nmock_df_high() {\n  cat <<'EOF' > /tmp/mockdf\n#!/usr/bin/env bash\necho \"Filesystem     1024-blocks    Used Available Capacity Mounted on\"\necho \"/dev/sda1       1000000   900000   100000  90% /\"\nEOF\n  chmod +x /tmp/mockdf\n}\n\nrun_test() {\n  local mock_path=$1\n  local expected_exit=$2\n  local expected_msg=$3\n  export PATH="$(dirname $mock_path):$PATH"\n  output=$(../src/disk-guardian.sh / 2>&1) || true\n  exit_code=$?\n  if [[ $exit_code -ne $expected_exit ]]; then\n    echo "FAIL: Expected exit $expected_exit, got $exit_code"\n    exit 1\n  fi\n  if ! echo "$output" | grep -q "$expected_msg"; then\n    echo "FAIL: Expected message '$expected_msg' not found"\n    exit 1\n  fi\n  echo "PASS: $expected_msg (exit $expected_exit)"\n}\n\n# Test low usage scenario\nmock_df_low\nrun_test /tmp/mockdf 0 "All clear!"\n\n# Test high usage scenario\nmock_df_high\nrun_test /tmp/mockdf 1 "Disk space critical!"\n
